      "id": "time-when-while",
      "title": "When vs. While",
      "group": "Simultaneous & Interruptions",
      "badge": "Action Sequence",
      "summary": "Mastering single pinpoint events (when) versus ongoing background atmospheres (while).",
      "formula": {
        "affirmative": "While + Past Continuous, Simple Past (interruption)  /  When + Simple Past, Main Clause",
        "negative": "Clauses can be negated independently according to standard tense rules.",
        "interrogative": "What happened while you were doing X?",
        "notes": "'While' usually takes continuous aspect; 'When' usually takes simple past."
      },
      "uses": [
        {
          "situation": "Sudden Interruption",
          "example": "While I was studying astronomy, a meteor flashed across the sky."
        },
        {
          "situation": "Two Simultaneous Actions",
          "example": "While Liam was editing the video, Sophia was drafting the script."
        },
        {
          "situation": "Sequential Triggers",
          "example": "When the clock struck twelve, the bells echoed through the valley."
        }
      ],
      "timeSignals": [
        "simultaneously",
        "at that very second",
        "during the storm"
      ],
